				player.addTempSkills("wzzs_jianliu_c", { global: "useCardAfter" });
				player.addTempSkills("wzzs_jianliu_g", { global: "useCardAfter" });
				player.storage.wzzs_jianliu_c = target;
				player.storage.wzzs_jianliu.remove('wzzs_jianliu2');
